// Some portions generated by Codex
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    createSeededRepository, deleteRepository, repositoryPageUrl, serverBaseUrl, uniqueRepositoryId, waitForRoute
} = require('./workbench-test-helpers.js');

const repository = uniqueRepositoryId('workbench-upload-state');
const rdf = '<urn:upload-state:s> <urn:upload-state:p> <urn:upload-state:o> .\n';

test.beforeAll(async ({ request }) => {
    await createSeededRepository(request, serverBaseUrl(), repository, { graphs: [] });
});
test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), repository);
});

async function openAdd(page) {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(repository, 'add'));
    await waitForRoute(page, 'add');
}

async function chooseSource(page, source) {
    await page.locator('label[for="source-' + source + '"]').click();
    await expect(page.locator('#source-' + source)).toBeChecked();
    if (source === 'file') {
        await page.locator('#file').setInputFiles({ name: 'upload-state.ttl', mimeType: 'text/turtle', buffer: Buffer.from(rdf) });
    } else if (source === 'text') {
        await page.locator('#text').fill(rdf);
    } else if (source === 'url') {
        await page.locator('#url').fill('https://data.example.test/upload-state.ttl');
    } else {
        // Pending-state tests exercise the server-file form without depending on the deployment's directory contents.
        await page.locator('#server-file').evaluate((select) => {
            select.append(new Option('upload-state.ttl', 'upload-state.ttl'));
        });
        await page.locator('#server-file').selectOption('upload-state.ttl');
    }
}

async function holdUploads(page, result = 'done') {
    let release;
    const gate = new Promise((resolve) => { release = resolve; });
    let posts = 0;
    const requests = [];
    await page.route((url) => url.pathname.endsWith('/add'), async (route) => {
        if (route.request().method() !== 'POST') { await route.continue(); return; }
        posts++;
        requests.push(route.request());
        await gate;
        if (route.request().failure()) { await route.abort('aborted'); return; }
        if (result === 'network') { await route.abort('failed'); return; }
        if (result === 'continue') { await route.continue(); return; }
        const records = [
            { type: 'head', version: 1 }, { type: 'view', id: 'add' },
            { type: 'end', metadata: { 'workbench-write': 'done' } }
        ];
        await route.fulfill({ status: 200, contentType: 'application/vnd.rdf4j.workbench+ndjson',
            headers: { 'X-Workbench-Write': 'done' }, body: records.map((record) => JSON.stringify(record)).join('\n') + '\n' });
    });
    return { release: () => release(), posts: () => posts,
        aborted: () => requests.some((request) => !!request.failure()) };
}

for (const source of ['file', 'text', 'url', 'server-file']) {
    test(`Upload ${source} greys the whole button, spins and blocks duplicate submission paths`, async ({ page }) => {
        await openAdd(page);
        await chooseSource(page, source);
        const held = await holdUploads(page);
        const button = page.locator('#add-upload-actions [type="submit"]');
        const action = button.locator('xpath=ancestor::*[contains(concat(" ", normalize-space(@class), " "), " workbench-action ")][1]');
        const readyColor = await action.evaluate((element) => getComputedStyle(element).backgroundColor);
        await button.click();
        await expect(button).toBeDisabled();
        await expect(page.locator('#add-form')).toHaveAttribute('aria-busy', 'true');
        await expect(action.locator('.workbench-submit-status__spinner')).toBeVisible();
        expect(await action.evaluate((element) => getComputedStyle(element).backgroundColor)).not.toBe(readyColor);
        await page.locator('#add-form').evaluate((form) => {
            form.requestSubmit();
            form.dispatchEvent(new SubmitEvent('submit', { bubbles: true, cancelable: true }));
            window.workbench.router.send(form);
            window.workbench.submitForm(form);
        });
        await page.locator('#context').press('Enter');
        expect(held.posts()).toBe(1);
        await expect(page.getByRole('dialog')).not.toBeVisible();
        held.release();
        await expect(page.locator('#add-form .workbench-submit-status')).toHaveAttribute('data-state', 'done');
        await expect(button).toBeEnabled();
        await expect(action.locator('.workbench-submit-status__spinner')).toHaveCount(0);
    });
}

test('selected file remains prominent and the drop instructions recover when the file is cleared', async ({ page }) => {
    await openAdd(page);
    const prompt = page.locator('.add-drop-zone__prompt');
    const formats = page.locator('.add-drop-zone__formats');
    await chooseSource(page, 'file');
    await expect(page.locator('.add-drop-zone__file')).toHaveText('upload-state.ttl');
    expect(Number(await prompt.evaluate((element) => getComputedStyle(element).opacity))).toBeLessThanOrEqual(0.4);
    expect(Number(await formats.evaluate((element) => getComputedStyle(element).opacity))).toBeLessThanOrEqual(0.4);
    expect(await page.locator('.add-drop-zone__file').evaluate((element) => getComputedStyle(element).opacity)).toBe('1');
    await page.locator('#file').setInputFiles([]);
    await expect(page.locator('.add-drop-zone__file')).toBeEmpty();
    expect(await prompt.evaluate((element) => getComputedStyle(element).opacity)).toBe('1');
});

test('an empty server-file selection keeps native validation and empty RDF text remains valid', async ({ page }) => {
    await openAdd(page);
    let posts = 0;
    page.on('request', (request) => { if (request.method() === 'POST') { posts++; } });
    await page.locator('label[for="source-server-file"]').click();
    await page.locator('#add-upload-actions [type="submit"]').click();
    await expect(page.locator('#add-form')).toHaveAttribute('aria-busy', 'false');
    expect(posts).toBe(0);
    await page.locator('label[for="source-text"]').click();
    await page.locator('#text').fill('');
    await page.locator('#add-upload-actions [type="submit"]').click();
    await expect(page.locator('#add-form .workbench-submit-status')).toHaveText('Data added');
    expect(posts).toBe(1);
});

test('a failed upload restores the button and can be retried with the same file', async ({ page }) => {
    await openAdd(page);
    await chooseSource(page, 'file');
    const held = await holdUploads(page, 'network');
    const button = page.locator('#add-upload-actions [type="submit"]');
    await button.click();
    await expect(button).toBeDisabled();
    held.release();
    await expect(page.locator('#add-form .workbench-submit-status')).toHaveAttribute('data-state', 'failed');
    await expect(button).toBeEnabled();
    await expect(page.locator('.add-drop-zone__file')).toHaveText('upload-state.ttl');
    await page.unrouteAll({ behavior: 'wait' });
    await button.click();
    await expect(page.locator('#add-form .workbench-submit-status')).toHaveText('Data added');
    await expect(button).toBeEnabled();
});

test('a rejected URL explains origin configuration and leaves a ready upload form', async ({ page }) => {
    await openAdd(page);
    await page.locator('label[for="source-url"]').click();
    await page.locator('#url').fill('file:///not-an-http-source.ttl');
    await page.locator('#add-upload-actions [type="submit"]').click();
    const error = page.locator('.workbench-callout--error');
    await expect(error).toContainText('org.eclipse.rdf4j.workbench.add-url-allowed-origins');
    await expect(error).toContainText('WEB-INF/web.xml');
    await expect(error).toContainText('comma-separated exact HTTP(S) origins');
    await expect(page.locator('#add-upload-actions [type="submit"]')).toBeEnabled();
    await expect(page.locator('#add-form')).toHaveAttribute('aria-busy', 'false');
    await expect(page.locator('#add-upload-actions .workbench-submit-status__spinner')).toHaveCount(0);
});

test('leaving a pending upload can be declined or confirmed and the next Add page is ready', async ({ page }) => {
    await openAdd(page);
    await chooseSource(page, 'text');
    const held = await holdUploads(page);
    const button = page.locator('#add-upload-actions [type="submit"]');
    await button.click();
    await page.locator('#navigation').getByRole('link', { name: 'Summary', exact: true }).click();
    const dialog = page.getByRole('dialog');
    await expect(dialog).toContainText('An upload is in progress');
    await dialog.getByRole('button', { name: 'Cancel', exact: true }).click();
    await expect(button).toBeDisabled();
    await page.locator('#navigation').getByRole('link', { name: 'Summary', exact: true }).click();
    await dialog.getByRole('button', { name: 'Leave and cancel upload' }).click();
    await waitForRoute(page, 'summary');
    expect(held.aborted()).toBe(true);
    held.release();
    await page.unrouteAll({ behavior: 'wait' });
    await openAdd(page);
    await expect(page.locator('#add-upload-actions [type="submit"]')).toBeEnabled();
    await expect(page.locator('#add-form')).toHaveAttribute('aria-busy', 'false');
});
